function changeLang(e){$.ajax({url:"/lib/webservices/hotel-profile-sm-ws.php",data:"changeLang="+e,type:"POST",success:function(a){var c=jQuery.parseJSON(a);$("#actualLang").val(""),$("#actualLang").val(e),$("#sharePreText").val(""),$("#sharePreText").val(c.pre),$("#shareStayText").val(""),$("#shareStayText").val(c.stay),$("#sharePostText").val(""),$("#sharePostText").val(c.post);var t=c.lang;$("#langSected").empty(),$("#langSected").append(t),checkShareTexts()}})}function checkShareTexts(){$.ajax({url:"/lib/webservices/hotel-profile-sm-ws.php",data:"checkShareTexts=1",type:"POST",success:function(e){var a=jQuery.parseJSON(e);a.forEach(function(e){"200"==e.code?($("#circle-"+e.lang).empty(),$("#circle-"+e.lang).append('<i class="fa fa-check-circle-o verde lang-ok">')):$("#circle-"+e.lang).empty()})}})}$(document).ready(function(){$(".langLia").click(function(e){e.preventDefault()}),changeLang($("#actualLang").val())});